from typing import List

class Pair:
    def __init__(self, start: int, end: int):
        self.start = start
        self.end = end

def max_chain_length(pairs: List[Pair], size: int) -> int:
    # Sort pairs by their end time
    pairs.sort(key=lambda x: x.end)

    # Initialize DP table with 1's for base case (each pair is its own chain)
    dp = [1] * size

    # Iterate through each pair to update the maximum length of chains ending at the current position
    for i in range(1, size):
        for j in range(i):
            if pairs[j].end < pairs[i].start:
                dp[i] = max(dp[i], dp[j] + 1)

    # The maximum value in DP array will be the result
    return max(dp)

# Example usage
pairs = [Pair(5, 24), Pair(15, 25), Pair(27, 40), Pair(50, 60)]
size = len(pairs)
print(max_chain_length(pairs, size))  # Output: 3

