def maximum_value(record_list):
    # Use a dictionary comprehension to convert tuples into key-value pairs where each tuple is (key, [values])
    value_dict = {record[0]: record[1] for record in record_list}

    # Find the maximum value for each key using max() function
    max_values = {key: max(values) for key, values in value_dict.items()}

    # Convert the result back into the desired format of list of tuples
    result = [(key, max_value) for key, max_value in max_values.items()]

    return result

