def find_k_product(tuples_list, k):
    # Check if k is within the range of the tuple indices
    if k <= len(tuples_list[0]) and k > 0:
        # Calculate the product by multiplying elements at the kth index of each tuple
        product = 1
        for tup in tuples_list:
            product *= tup[k-1]
        return product
    else:
        raise ValueError("k must be between 1 and the length of the longest tuple")

# Example usage
print(find_k_product([(5, 6, 7), (1, 3, 5), (8, 9, 19)], 2))  # Output: 665

