def first_digit(n):
    # Calculate the factorial of n
    fact = 1
    for i in range(2, n + 1):
        fact *= i

    # Convert the factorial to a string and find the first character which is a non-zero digit
    first_non_zero = next((c for c in str(fact) if c != '0'), None)

    return int(first_non_zero)

# Example usage:
assert first_digit(5) == 1

