def min_jumps(arr, n):
    # Initialize the dp array to store the minimum jumps needed to reach the end of the array
    dp = [float('inf')] * n
    dp[0] = 0

    # Iterate through the array to fill the dp array with the minimum jumps
    for i in range(1, n):
        for j in range(i):
            if arr[j] + j >= i:
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[n - 1]

