def harmonic_sum(n):
    """
    Calculate the harmonic sum of n-1.

    Args:
    n (int): The number for which the harmonic sum is to be calculated.

    Returns:
    float: The harmonic sum of n-1.
    """
    if n <= 0:
        return 0.0
    else:
        return 1 / n + harmonic_sum(n - 1)

