def divisible_by_digits(start, end):
    def has_only_digits(n):
        return all(digit in '0123456789' for digit in str(n))

    def is_divisible_by_all_digits(num):
        while num > 0:
            if num % (num % 10) != 0:
                return False
            num //= 10
        return True

    result = []
    for num in range(start, end + 1):
        if has_only_digits(num) and is_divisible_by_all_digits(num):
            result.append(num)
    return result

