def check_min_heap(arr, index):
    # Base condition: If there's only one element or no elements, it is considered as a valid min heap.
    if index * 2 + 1 >= len(arr):
        return True

    # Check if the current node is smaller than its left child
    if arr[index] > arr[index * 2 + 1]:
        return False

    # Check if the current node is smaller than its right child (if exists)
    if index * 2 + 2 < len(arr) and arr[index] > arr[index * 2 + 2]:
        return False

    # Recursively check the children nodes
    return check_min_heap(arr, index * 2 + 1) and check_min_heap(arr, index * 2 + 2)

