import heapq

def nth_super_ugly_number(n, primes):
    # Initialize the heap with the first ugly number 1 and the prime numbers
    heap = [1]
    seen = {1}

    for _ in range(n - 1):
        # Pop the smallest ugly number from the heap
        current = heapq.heappop(heap)

        # Generate new ugly numbers by multiplying the current number with each prime number
        for prime in primes:
            next_number = current * prime
            # Add the new number to the heap if it hasn't been seen before
            if next_number not in seen:
                heapq.heappush(heap, next_number)
                seen.add(next_number)

    return heapq.heappop(heap)  # Return the n-th ugly number

