def find_longest_conseq_subseq(arr, n):
    # Create a dictionary to keep track of the count of each element
    count = {}

    # Populate the count dictionary with all elements in the array
    for num in arr:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    max_length = 0
    current_length = 1

    # Iterate through the sorted array to find consecutive sequences
    for i in range(1, n):
        if arr[i] - arr[i-1] == 1 and count[arr[i]] > 0 and count[arr[i-1]] > 0:
            current_length += count[arr[i]]
        else:
            current_length = 1

        max_length = max(max_length, current_length)

    return max_length

