def find_longest_conseq_subseq(nums, n):
    # Initialize the array 'dp' with all elements set to 1, indicating each element is its own subsequence
    dp = [1] * n

    # Iterate through the array to build the 'dp' array where dp[i] represents the length of the longest subsequence ending at nums[i]
    for i in range(1, n):
        if nums[i] == nums[i-1]+1:
            dp[i] = dp[i-1] + 1

    # The maximum value in the 'dp' array will be the length of the longest subsequence
    return max(dp)

