def is_Isomorphic(s: str, t: str) -> bool:
    # If lengths of both strings are different, they cannot be isomorphic
    if len(s) != len(t):
        return False

    s_map = {}
    t_map = {}

    for i in range(len(s)):
        # Check if character in s_map or t_map has already been used
        if s[i] in s_map and s_map[s[i]] != t[i]:
            return False
        if t[i] in t_map and t_map[t[i]] != s[i]:
            return False

        # Update maps with the current characters
        s_map[s[i]] = t[i]
        t_map[t[i]] = s[i]

    return True

