def super_seq(str1, str2, n, m):
    # Create a matrix to store lengths of longest common subsequence
    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]

    # Fill the dp matrix in bottom-up manner
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The length of the super sequence is the sum of lengths of str1 and str2 minus the length of their LCS
    return n + m - dp[n][m]

# Test the function with the provided example
print(super_seq("AGGTAB", "GXTXAYB", 6, 7))  # Output: 9

