def super_seq(str1, str2, m, n):
    # If either string is empty, return the length of the other string
    if m == 0:
        return n
    if n == 0:
        return m

    # If last characters of both strings are same, then count the last character once
    if str1[m-1] == str2[n-1]:
        return 1 + super_seq(str1, str2, m-1, n-1)

    # Otherwise, consider all three cases: 
    # 1) Not taking the last char from str1
    # 2) Not taking the last char from str2
    # 3) Taking both the last chars from both str1 and str2
    return min(super_seq(str1, str2, m-1, n), super_seq(str1, str2, m, n-1), super_seq(str1, str2, m-1, n-1)) + 1

