def nCr_mod_p(n, r, p):
    # Base cases
    if r > n or r < 0:
        return "Invalid input"
    elif r == 0 or r == n:
        return 1

    # Initialize result
    C = [0] * (r + 1)
    C[0] = 1  # Base condition

    for i in range(1, n + 1):
        # Compute next row using previous row
        for j in range(min(i, r), 0, -1):
            C[j] = (C[j] + C[j-1]) % p

    return C[r]

# Example usage
print(nCr_mod_p(10, 2, 13))  # Output: 6

