def nCr_mod_p(n, r, p):
    # Helper function to calculate factorial using recursion
    def factorial(x):
        if x == 0 or x == 1:
            return 1
        else:
            return x * factorial(x - 1)

    # Calculate nCr using modular arithmetic
    n_fact = factorial(n)
    r_fact = factorial(r)
    n_r_fact = factorial(n - r)

    # Compute the result using modular inverse
    inv_r_fact = pow(r_fact, p - 2, p)

    return (n_fact * inv_r_fact) % p

